const fs=require('fs'),vm=require('vm'),assert=require('assert');
const ROOT=require('path').resolve(process.argv[2]||'math-quiz')+'/';const ctx=vm.createContext({});for(const f of ['v9-bank.js','v10-daily.js','v10-figures.js'])vm.runInContext(fs.readFileSync(ROOT+f,'utf8'),ctx);
function expected(ch){const v=ch.v;switch(ch.op){case 'subtract':return v[0]-v[1];case 'overlap':return v[0]+v[1]-v[2];case 'segments':return Array.from({length:v[0]},(_,i)=>i).reduce((a,b)=>a+b,0);case 'segment-ratio':return v[2]*v[0]/(v[0]+v[1]);case 'same':return v[0];case 'half':return v[0]/2;case 'supp-eq':return (180-v[1]-v[3])/(v[0]+v[2]);case 'equal-eq':return (v[3]-v[1])/(v[0]-v[2]);case 'threequarters':return v[0]*.75;case 'supplement':return 180-v[0];case 'possible':{const a=[...v].sort((a,b)=>a-b);return a[0]+a[1]>a[2];}case 'range-count':case 'range-sum':{let xs=[];for(let x=1;x<v[0]+v[1];x++)if(x+v[0]>v[1]&&x+v[1]>v[0])xs.push(x);return ch.op==='range-count'?xs.length:xs.reduce((a,b)=>a+b,0);}case 'fromvertex':return v[0]-3;case 'diagonals':{let n=0;for(let i=0;i<v[0];i++)for(let j=i+1;j<v[0];j++)if(j-i!==1&&j-i!==v[0]-1)n++;return n;}case 'diagonal-reverse':{for(let n=3;n<100;n++)if(n*(n-3)/2===v[0])return n;break;}case 'fromvertex-reverse':return v[0]+3;case 'triangle-inner':return 180-v[0]-v[1];case 'triangle-eq':return (180-v[0])/4;case 'angle-ratio':return 180*Math.max(...v)/v.reduce((a,b)=>a+b,0);case 'angle-diff':return (v[0]+v[1])/2;case 'interior-sum':return (v[0]-2)*180;case 'interior-reverse':return v[0]/180+2;case 'regular-inner':return 180-360/v[0];case 'regular-reverse':return 360/(180-v[0]);case 'exterior-sum':return 360;case 'regular-outer':return 360/v[0];case 'exterior-reverse':return 360/v[0];case 'exterior-missing':return 360-v.reduce((a,b)=>a+b,0);default:throw Error('unhandled '+ch.op);}}
const angle=(a,o,b)=>{const x=[a[0]-o[0],a[1]-o[1]],y=[b[0]-o[0],b[1]-o[1]];return Math.acos(Math.max(-1,Math.min(1,(x[0]*y[0]+x[1]*y[1])/(Math.hypot(...x)*Math.hypot(...y)))))*180/Math.PI;};
const all={days:0,questions:0,arithmetic:0,figures:0,geometricChecks:0,consecutiveIdentical:[]};let previous;
for(let d=0;d<366;d++){
 const date=new Date(Date.UTC(2026,8,10)+d*86400000).toISOString().slice(0,10);ctx.date=date;const b=vm.runInContext('DailyMath.make(date)',ctx);assert.equal(b.length,60);
 assert.equal(JSON.stringify(b),JSON.stringify(vm.runInContext('DailyMath.make(date)',ctx)),'Deterministic daily content');
 for(let i=0;i<b.length;i++){const q=b[i];all.questions++;assert.equal(new Set([q.a,...q.o]).size,4);if(previous&&q.q===previous[i].q)all.consecutiveIdentical.push([date,q.id]);
  if(q.check){const exp=expected(q.check);assert(Math.abs(Number(exp)-Number(q.check.answer))<1e-8,`${date} ${q.id} ${exp} != ${q.check.answer}`);if(typeof exp!=='boolean')assert(Math.abs(parseFloat(q.a)-exp)<1e-6);else assert.equal(q.a,exp?'작도할 수 있다':'작도할 수 없다');all.arithmetic++;}
  if(q.fig){ctx.q=q;const s=vm.runInContext('DailyFigures.generate(q)',ctx);assert(!/NaN|Infinity|undefined/.test(s),`${q.id} SVG invalid`);all.figures++;
   const a=vm.runInContext('DailyFigures.generate.lastAudit',ctx);for(const c of a){all.geometricChecks++;if(c.kind==='triangle'){c.angles.forEach((x,i)=>assert(Math.abs(angle(c.points[(i+1)%3],c.points[i],c.points[(i+2)%3])-x)<1e-6));}if(c.kind==='sas'){assert(Math.abs(angle(c.points[1],c.points[0],c.points[2])-c.angle)<1e-6);}if(c.kind==='sides'){const ls=c.points.map((p,i)=>Math.hypot(p[0]-c.points[(i+1)%3][0],p[1]-c.points[(i+1)%3][1]));const r=ls[0]/c.expected[0];ls.forEach((v,i)=>assert(Math.abs(v/c.expected[i]-r)<1e-6));}if(c.kind==='congruent'){for(let i=0;i<3;i++)for(let j=i+1;j<3;j++)assert(Math.abs(Math.hypot(c.left[i][0]-c.left[j][0],c.left[i][1]-c.left[j][1])-Math.hypot(c.right[i][0]-c.right[j][0],c.right[i][1]-c.right[j][1]))<1e-7);}}
  }
 }
 previous=b;all.days++;
}
assert.equal(all.consecutiveIdentical.length,0,'All daily prompts change');
assert.equal(vm.runInContext('DailyMath.dateKey(Date.parse("2026-09-10T14:59:59.999Z"))',ctx),'2026-09-10');assert.equal(vm.runInContext('DailyMath.dateKey(Date.parse("2026-09-10T15:00:00Z"))',ctx),'2026-09-11');
console.log(JSON.stringify(all,null,2));
